parameters.jsCode:
// ==========================================
// VALIDATE CONFIGURATION (Phase 2)
// ==========================================
const input = $input.first().json;
const errors = [];

const isTrue = (v, d) => {
  if (typeof v === 'boolean') return v;
  if (v === undefined || v === null || String(v).trim() === '') return d;
  return /^(true|yes|y|1)$/i.test(String(v).trim());
};
const asNum = (v, d) => {
  if (v === '' || v === null || v === undefined) return d;
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
};
const asList = v => Array.isArray(v)
  ? v.map(x => String(x).trim()).filter(Boolean)
  : String(v ?? '').split(/[,;\n]+/).map(s => s.trim()).filter(Boolean);
const asJson = (v, d, label) => {
  if (v && typeof v === 'object') return v;
  const s = String(v ?? '').trim();
  if (!s) return d;
  try { return JSON.parse(s); } catch (e) { errors.push(`${label} is not valid JSON`); return d; }
};

// Spreadsheet ID (a full URL is accepted too)
let spreadsheetId = String(input.spreadsheetId ?? '').trim();
const urlMatch = spreadsheetId.match(/\/d\/([a-zA-Z0-9_-]+)/);
if (urlMatch) spreadsheetId = urlMatch[1];

const adminEmail = String(input.adminEmail ?? '').trim();
const channel = String(input.channel || 'gmail').trim().toLowerCase();
const default_channel = String(input.default_channel || 'gmail').trim().toLowerCase();
const target_type = String(input.target_type || '').trim().toLowerCase();
const packages = asJson(input.packages_json, {}, 'packages_json');
const package_by_category = asJson(input.package_by_category_json, {}, 'package_by_category_json');
const pkgName = String(input.package || '').trim();
const attachment_mode = String(input.attachment_mode || 'none').trim().toLowerCase();
const attachment_file_ids = asList(input.attachment_file_ids);
const dry_run = isTrue(input.dry_run, true);
const require_admin_approval = isTrue(input.require_admin_approval, true);
const default_country_code = String(input.default_country_code || '+92').trim();
const allowed_country_codes = asList(input.allowed_country_codes).map(c => '+' + c.replace(/^\+/, ''));
if (!allowed_country_codes.includes(default_country_code)) allowed_country_codes.push(default_country_code);

const limits = {
  max_per_run: asNum(input.max_per_run, 50),
  gmail_per_day: asNum(input.gmail_per_day, 100),
  whatsapp_per_day: asNum(input.whatsapp_per_day, 200),
  delay_min: asNum(input.delay_min, 20),
  delay_max: asNum(input.delay_max, 60)
};

// ---- validation ----
if (!spreadsheetId || spreadsheetId === 'PASTE_GOOGLE_SHEET_ID') errors.push('spreadsheetId missing');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(adminEmail) || adminEmail === 'contact@example.com') errors.push('adminEmail missing or still the placeholder');
if (!['gmail', 'whatsapp', 'both', 'auto'].includes(channel)) errors.push(`Invalid channel: "${channel}" (use gmail | whatsapp | both | auto)`);
if (!['gmail', 'whatsapp'].includes(default_channel)) errors.push(`Invalid default_channel: "${default_channel}"`);
if (!['person', 'rows', 'category', 'search', 'checkbox'].includes(target_type)) errors.push(`Invalid target_type: "${target_type}"`);

const hasCat = asList(input.target_position).length || asList(input.target_city).length || asList(input.target_tag).length;
if (target_type === 'person' && !String(input.target_person ?? '').trim()) errors.push('target_person missing');
if (target_type === 'rows' && !asList(input.target_rows).length) errors.push('target_rows missing');
if (target_type === 'category' && !hasCat) errors.push('Category target needs target_position, target_city or target_tag');
if (target_type === 'search' && !String(input.search_query ?? '').trim() && !hasCat && !String(input.target_person ?? '').trim()) errors.push('search_query missing');

if (!pkgName || !packages[pkgName]) errors.push(`Package "${pkgName}" not found in packages_json`);
if (!['none', 'specific', 'shuffle'].includes(attachment_mode)) errors.push(`Invalid attachment_mode: "${attachment_mode}"`);
if (['specific', 'shuffle'].includes(attachment_mode) && !attachment_file_ids.length) errors.push('Attachment file IDs missing');

const usesWa = ['whatsapp', 'both', 'auto'].includes(channel);
if (usesWa && !dry_run && !String(input.wa_phone_number_id ?? '').trim()) errors.push('wa_phone_number_id missing (needed to send on WhatsApp)');
if (!/^\+\d{1,3}$/.test(default_country_code)) errors.push('default_country_code must look like +92');
if (limits.max_per_run < 1) errors.push('max_per_run must be at least 1');
if (limits.gmail_per_day < 1) errors.push('gmail_per_day must be at least 1');
if (limits.whatsapp_per_day < 1) errors.push('whatsapp_per_day must be at least 1');
if (limits.delay_min < 0) errors.push('delay_min cannot be negative');
if (limits.delay_max < limits.delay_min) errors.push('delay_max must be greater than or equal to delay_min');

const gmailCheck = String(input.check_text ?? '').trim()
  || String(packages[pkgName]?.gmail?.subject ?? '').replace(/\{\{.*?\}\}/g, '').trim();

const now = new Date();
const run_id = input.run_id || 'RUN-' + now.toISOString().replace(/[-:T.Z]/g, '').slice(0, 14);

return [{
  json: {
    ...input,
    spreadsheetId,
    adminEmail,
    channel,
    default_channel,
    target_type,
    packages,
    package_by_category,
    package: pkgName,
    attachment_mode,
    attachment_file_ids,
    dry_run,
    require_admin_approval,
    strict_mode: isTrue(input.strict_mode, false),
    check_mx_record: isTrue(input.check_mx_record, true),
    fuzzy: isTrue(input.fuzzy, true),
    default_country_code,
    allowed_country_codes,
    on_document_problem: String(input.on_document_problem || 'skip_document').trim().toLowerCase(),
    search_max_results: asNum(input.search_max_results, 5),
    search_min_score: asNum(input.search_min_score, 0.5),
    wa_api_version: String(input.wa_api_version || 'v21.0').trim(),
    wa_phone_number_id: String(input.wa_phone_number_id ?? '').trim(),
    gmail_max_mb: asNum(input.gmail_max_mb, 25),
    wa_doc_max_mb: asNum(input.wa_doc_max_mb, 100),
    opt_out_text: String(input.opt_out_text ?? '').trim(),
    gmail_check_text: gmailCheck,
    ...limits,
    run_id,
    started_at: now.toISOString(),
    config_valid: errors.length === 0,
    validation_errors: errors
  }
}];

// ---------- shared helpers ----------
const normKey = s => String(s ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
const lev = (a, b) => {
  if (a === b) return 0;
  const m = a.length, n = b.length;
  if (!m) return n;
  if (!n) return m;
  let prev = Array.from({ length: n + 1 }, (_, j) => j);
  for (let i = 1; i <= m; i++) {
    const cur = [i];
    for (let j = 1; j <= n; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = cur;
  }
  return prev[n];
};
const sim = (a, b) => {
  const na = normKey(a), nb = normKey(b);
  if (!na || !nb) return 0;
  if (na === nb) return 1;
  if (Math.min(na.length, nb.length) >= 3 && (na.includes(nb) || nb.includes(na))) return 0.9;
  return 1 - lev(na, nb) / Math.max(na.length, nb.length);
};
const getter = row => {
  const map = {};
  for (const k of Object.keys(row || {})) map[normKey(k)] = row[k];
  return (...names) => {
    for (const n of names) {
      const v = map[normKey(n)];
      if (v !== undefined && v !== null && String(v).trim() !== '') return v;
    }
    return '';
  };
};

// ==========================================
// NORMALIZE & CLEAN CONTACTS
// Tags/Category column has been replaced by Position.
// Therefore category is also populated from Position for backward compatibility.
// ==========================================
const cfg = $('Validate Configuration').first().json;
const defDial = String(cfg.default_country_code || '+92').replace('+', '');
const allowed = (cfg.allowed_country_codes || []).map(c => String(c).replace(/^\+?/, ''));
const INVIS = /[​-‏‪-‮⁠﻿ ]/g;

const review = reason => ({ clean: '', status: 'Needs review', reason });

function problemWith(out) {
  const digits = out.slice(1);
  if (defDial === '92' && digits.startsWith('92')) {
    const rest = digits.slice(2);
    if (rest.length < 10) return `only ${rest.length} digits after +92`;
    if (rest.length > 10) return `too many digits (${rest.length} after +92)`;
    if (rest[0] !== '3') return 'not a mobile number (a Pakistani mobile starts with 3)';
    return '';
  }
  if (digits.length < 8 || digits.length > 15) return `invalid length (${digits.length} digits)`;
  if (!(digits.startsWith(defDial) || allowed.some(c => digits.startsWith(c)))) return 'country code is not in the allowed list';
  return '';
}

function cleanOne(tok) {
  const original = String(tok).replace(INVIS, '').trim();
  let s = original;
  if (!s) return { clean: '', status: '', reason: '' };
  const sci = s.match(/^(\d+)(?:\.(\d+))?e\+?(\d+)$/i);
  if (sci) {
    const digits = sci[1] + (sci[2] || '');
    const total = sci[1].length + Number(sci[3]);
    if (digits.length !== total) return review('scientific notation (Excel lost digits)');
    s = digits;
  }
  s = s.replace(/\(\s*0\s*\)/g, '');
  const hasPlus = /^\(?\s*\+/.test(s);
  let d = s.replace(/\D/g, '');
  let out;
  if (hasPlus) {
    if (d.startsWith(defDial + '0') && d.length === defDial.length + 11) d = defDial + d.slice(defDial.length + 1);
    out = '+' + d;
  } else if (d.startsWith('00')) {
    out = '+' + d.slice(2);
  } else if (d.startsWith(defDial) && d.length === defDial.length + 10) {
    out = '+' + d;
  } else if (d.startsWith('0')) {
    out = '+' + defDial + d.slice(1);
  } else if (d.length === 10) {
    out = '+' + defDial + d;
  } else {
    return review(`unrecognized format (${d.length} digits)`);
  }
  const problem = problemWith(out);
  if (problem) return review(problem);
  return { clean: out, status: out === original ? 'Valid' : 'Fixed', reason: '' };
}

function normalizeMobile(raw) {
  const text = String(raw ?? '').replace(INVIS, '').trim();
  if (!text) return { clean: '', status: '', reason: '', options: [] };
  const tokens = text.split(/[\/,;|\n]|\s+or\s+/i).map(t => t.trim()).filter(t => t.replace(/\D/g, '').length >= 6);
  if (!tokens.length) return { ...review('no usable number found'), options: [] };
  const results = tokens.map(cleanOne);
  const valid = results.filter(r => r.clean);
  if (tokens.length === 1) return { ...results[0], options: valid.map(r => r.clean) };
  if (valid.length) return { clean: valid[0].clean, status: 'Fixed', reason: 'multiple numbers in one cell, using the first valid one', options: valid.map(r => r.clean) };
  return { ...results[0], options: [] };
}

const truthy = v => /^(yes|y|true|1|x|✓|✔)$/i.test(String(v ?? '').trim());
// Google Sheets node is named Contacts; use current input so the node name never breaks.
const rows = $input.all().map(i => i.json);
const contacts = [];

for (const raw of rows) {
  const g = getter(raw);
  const name = String(g('Name', 'Full Name')).trim();
  const email = String(g('Email', 'E-mail')).trim().toLowerCase();
  const mobileRaw = g('Mobile', 'Mobile Number', 'Phone', 'Phone Number', 'WhatsApp');
  if (!name && !email && !String(mobileRaw).trim()) continue;

  const m = normalizeMobile(mobileRaw);
  const cityCountry = String(g('City / Country', 'City', 'Location')).split(',').map(s => s.trim()).filter(Boolean);
  const country = cityCountry.slice(1).join(', ') || String(g('Country')).trim();
  const exp = parseFloat(g('Experience (years)', 'Experience', 'Years of Experience'));
  const skills = String(g('Skills')).trim();
  const pref = String(g('Preferred Channel')).trim().toLowerCase();

  const position = String(g(
    'Position',
    'Job Position',
    'Job Title',
    'Role',
    'Title'
  )).trim();

  const statusCell = m.status
    ? (m.status === 'Needs review' && m.reason ? `Needs review: ${m.reason}` : m.status)
    : '';
  const existingClean = String(g('mobile_clean', 'Mobile (Clean)')).trim();
  const existingStatus = String(g('number_status', 'Number Status')).trim();

  contacts.push({
    row_number: raw.row_number,
    name,
    email,
    email_valid: /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email),
    mobile_raw: String(mobileRaw ?? '').trim(),
    mobile_clean: m.clean,
    number_status: m.status,
    number_reason: m.reason,
    number_status_cell: statusCell,
    mobile_options: m.options,
    position,
    // Backward compatibility: old target/package nodes can still use category/tag.
    category: position,
    tag: position,
    skills,
    skills_list: skills.split(/[,;\/|]+/).map(s => s.trim()).filter(Boolean),
    city: cityCountry[0] || '',
    country,
    experience: Number.isFinite(exp) ? exp : null,
    preferred_channel: ['gmail', 'whatsapp', 'both'].includes(pref) ? pref : '',
    wa_optin: truthy(g('WhatsApp Opt-in', 'WhatsApp Opt in', 'Opt-in')),
    last_inbound: String(g('Last Inbound')).trim(),
    selected: truthy(g('Select', 'Selected', 'Send', 'Checkbox')),
    existing_gmail_status: String(g('Gmail Status')).trim(),
    existing_wa_status: String(g('WhatsApp Status')).trim(),
    existing_last_contacted: String(g('Last Contacted')).trim(),
    sheet_changed: !!String(mobileRaw ?? '').trim() && (m.clean !== existingClean || statusCell !== existingStatus),
    raw
  });
}

// Duplicate mobile/email detection
const byMobile = new Map();
const byEmail = new Map();
for (const c of contacts) {
  if (c.mobile_clean) {
    if (!byMobile.has(c.mobile_clean)) byMobile.set(c.mobile_clean, []);
    byMobile.get(c.mobile_clean).push(c);
  }
  if (c.email) {
    if (!byEmail.has(c.email)) byEmail.set(c.email, []);
    byEmail.get(c.email).push(c);
  }
}
const identity = c => c.email || normKey(c.name);
for (const c of contacts) {
  c.mobile_conflict = false;
  c.conflict_rows = [];
  c.dup_in_sheet = false;
  const sameMobile = c.mobile_clean ? byMobile.get(c.mobile_clean) : null;
  if (sameMobile && sameMobile.length > 1) {
    const others = sameMobile.filter(o => o !== c);
    const different = others.filter(o => identity(o) !== identity(c));
    if (different.length) {
      c.mobile_conflict = true;
      c.conflict_rows = different.map(o => o.row_number);
    }
    if (others.length > different.length) c.dup_in_sheet = true;
  }
  const sameEmail = c.email ? byEmail.get(c.email) : null;
  if (sameEmail && sameEmail.length > 1) c.dup_in_sheet = true;
}

if (!contacts.length) return [{ json: { _empty: true } }];
return contacts.map(c => ({ json: c }));

// ---------- shared helpers ----------
const normKey = s => String(s ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
const lev = (a, b) => {
  if (a === b) return 0;
  const m = a.length, n = b.length;
  if (!m) return n;
  if (!n) return m;
  let prev = Array.from({ length: n + 1 }, (_, j) => j);
  for (let i = 1; i <= m; i++) {
    const cur = [i];
    for (let j = 1; j <= n; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = cur;
  }
  return prev[n];
};
const sim = (a, b) => {
  const na = normKey(a), nb = normKey(b);
  if (!na || !nb) return 0;
  if (na === nb) return 1;
  if (Math.min(na.length, nb.length) >= 3 && (na.includes(nb) || nb.includes(na))) return 0.9;
  return 1 - lev(na, nb) / Math.max(na.length, nb.length);
};
const toList = v => Array.isArray(v)
  ? v.map(x => String(x).trim()).filter(Boolean)
  : String(v ?? '').split(/[,;\n]+/).map(s => s.trim()).filter(Boolean);
const digitsOf = v => String(v ?? '').replace(/\D/g, '');
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const getter = row => {
  const map = {};
  for (const k of Object.keys(row || {})) map[normKey(k)] = row[k];
  return (...names) => {
    for (const n of names) {
      const v = map[normKey(n)];
      if (v !== undefined && v !== null && String(v).trim() !== '') return v;
    }
    return '';
  };
};
const safeAll = name => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };

// ==========================================
// SMART SEARCH (filters + keyword + fuzzy, ranked)
// ==========================================
const cfg = $('Validate Configuration').first().json;
const defDial = String(cfg.default_country_code || '+92').replace('+', '');
const phoneCore = v => digitsOf(v).replace(/^00/, '').replace(new RegExp('^' + defDial), '').replace(/^0+/, '');
const contacts = $input.all().map(i => i.json).filter(c => c && !c._empty);
const thr = cfg.fuzzy === false ? 0.9 : 0.82;

const vocab = { position: new Map(), skill: new Map(), city: new Map(), category: new Map() };
const addV = (t, v) => { const s = String(v || '').trim(); if (s) vocab[t].set(normKey(s), s); };
for (const c of contacts) {
  addV('position', c.position); addV('city', c.city); addV('category', c.category);
  for (const s of c.skills_list || []) addV('skill', s);
}

// Stricter than sim(): a phrase only matches a term if it is (nearly) equal, or is a single word that is part of the term
const gramSim = (gram, term) => {
  const na = normKey(gram), nb = normKey(term);
  if (!na || !nb) return 0;
  if (na === nb) return 1;
  if (!/\s/.test(String(gram).trim()) && na.length >= 3 && nb.includes(na)) return 0.9;
  return 1 - lev(na, nb) / Math.max(na.length, nb.length);
};
const criteria = [];
const addC = (type, value, label, weight = 1) => {
  if (!criteria.some(c => c.type === type && normKey(c.value) === normKey(value))) criteria.push({ type, value, label, weight });
};
for (const p of toList(cfg.target_position)) addC('position', p, `position: ${p}`);
for (const p of toList(cfg.target_city)) addC('city', p, `city: ${p}`);
for (const p of toList(cfg.target_tag)) addC('category', p, `category: ${p}`);
for (const w of String(cfg.target_person || '').split(/\s+/).filter(w => normKey(w).length >= 2)) addC('name', w, `name: ${w}`);

let rest = String(cfg.search_query || '');
const yr = rest.match(/(\d+(?:\.\d+)?)\s*\+?\s*(?:years?|yrs?)\b/i);
if (yr) { addC('years', Number(yr[1]), `${yr[1]}+ years of experience`); rest = rest.replace(yr[0], ' '); }
const ph = rest.match(/(\+?\d[\d\s\-()]{2,}\d)/);
if (ph && digitsOf(ph[1]).length >= 3) { addC('phone', phoneCore(ph[1]), `mobile ${ph[1].trim()}`, 3); rest = rest.replace(ph[0], ' '); }

const stop = new Set(('find the a an with who whose person people candidate candidates and in at of for to mobile number ends end ending phone years year ' +
  'experience has have having knows know skilled skills skill from based located email him her them send that one this requirement requirements interview schedule whatsapp ' +
  'is are or on by me my').split(' '));
const words = rest.replace(/[,;]+/g, ' ').split(/\s+/).filter(Boolean);
const used = new Array(words.length).fill(false);
for (const size of [3, 2, 1]) {
  for (let i = 0; i + size <= words.length; i++) {
    if (used.slice(i, i + size).some(Boolean)) continue;
    const gram = words.slice(i, i + size).join(' ');
    if (size === 1 && (stop.has(gram.toLowerCase()) || normKey(gram).length < 2)) continue;
    let best = { type: null, term: null, score: 0 };
    for (const type of ['position', 'skill', 'city', 'category']) {
      for (const term of vocab[type].values()) {
        const sc = gramSim(gram, term);
        if (sc > best.score) best = { type, term, score: sc };
      }
    }
    if (best.score >= thr) {
      addC(best.type, best.term, `${best.type}: ${best.term}`);
      for (let j = i; j < i + size; j++) used[j] = true;
    }
  }
}
words.forEach((w, i) => {
  if (!used[i] && !stop.has(w.toLowerCase()) && normKey(w).length >= 3) addC('name', w, `name: ${w}`);
});

if (!criteria.length) {
  return [{ json: { _empty: true, message: 'The search query had no recognizable requirement (position, skill, city, years, name or mobile).' } }];
}

const memo = new Map();
const msim = (a, b) => {
  const k = a + '\u0001' + b;
  if (!memo.has(k)) memo.set(k, sim(a, b));
  return memo.get(k);
};
const total = criteria.reduce((s, c) => s + c.weight, 0);
const scored = [];
for (const c of contacts) {
  let got = 0;
  const matched = [], missed = [];
  for (const cr of criteria) {
    let ok = false;
    switch (cr.type) {
      case 'position': ok = msim(c.position, cr.value) >= thr; break;
      case 'skill': ok = (c.skills_list || []).some(s => msim(s, cr.value) >= thr); break;
      case 'city': ok = msim(c.city, cr.value) >= thr || msim(c.country, cr.value) >= thr; break;
      case 'category': ok = msim(c.category, cr.value) >= thr; break;
      case 'years': ok = c.experience !== null && c.experience >= cr.value; break;
      case 'phone': ok = [c.mobile_clean, ...(c.mobile_options || [])].some(m => m && digitsOf(m).endsWith(cr.value)); break;
      case 'name': ok = String(c.name).split(/\s+/).some(w => msim(w, cr.value) >= thr); break;
    }
    if (ok) { got += cr.weight; matched.push(cr.label); } else missed.push(cr.label);
  }
  if (got > 0) scored.push({ c, score: got / total, matched, missed });
}
scored.sort((a, b) => b.score - a.score || (b.c.experience ?? 0) - (a.c.experience ?? 0));

const max = Math.max(1, cfg.search_max_results || 5);
let top = scored.filter(s => s.score >= cfg.search_min_score).slice(0, max);
let weak = false;
if (!top.length) { top = scored.slice(0, 3); weak = true; }
if (!top.length) {
  return [{ json: { _empty: true, message: 'No one in the sheet matches this requirement.' } }];
}
return top.map((s, i) => ({
  json: { ...s.c, match_score: Math.round(s.score * 100), matched: s.matched, missed: s.missed, search_rank: i + 1, search_weak: weak }
}));

// ---------- shared helpers ----------
