    row_number: it.row_number, person_key: it.person_key, name: it.name, email: it.email,
    mobile_clean: it.mobile_clean, mobile_raw: it.mobile_raw, number_status: it.number_status, number_reason: it.number_reason,
    position: it.position, city: it.city, category: it.category, package: it.package, channel: ch,
    status, reason, warnings, message_type,
