function text(value) {
  return String(value === undefined || value === null ? '' : value).trim();
}

function key(value) {
  return text(value).toLowerCase().replace(/[^a-z0-9]/g, '');
}

function field(row, names) {
  var wanted = names.map(key);
  var headers = Object.keys(row || {});

  for (var i = 0; i < headers.length; i++) {
    if (wanted.indexOf(key(headers[i])) !== -1) {
      var value = row[headers[i]];
      if (text(value) !== '') return value;
    }
  }
  return '';
}

function samePerson(a, b) {
  var aRow = text(field(a, ['row_number', 'Row Number', 'Row ID', 'row']));
  var bRow = text(field(b, ['row_number', 'Row Number', 'Row ID', 'row']));
  if (aRow && bRow && aRow === bRow) return true;

  var aEmail = text(field(a, ['email', 'Email'])).toLowerCase();
  var bEmail = text(field(b, ['email', 'Email'])).toLowerCase();
  if (aEmail && bEmail && aEmail === bEmail) return true;

  return false;
}

function findSource(row, rows) {
  for (var i = 0; i < rows.length; i++) {
    if (samePerson(row, rows[i])) return rows[i];
  }
  return {};
}

var output = [];
