    field(source, ['position', 'Position', 'Job Position', 'Job Title', 'Role', 'Title'])
  );

  var missing = item.missing_fields;
  if (!Array.isArray(missing)) missing = [];

  var newMissing = missing.filter(function (name) {
    return key(name) !== 'position';
  });

  var subject = text(item.gmail_subject) || text(source.gmail_subject);
  var body = text(item.gmail_body) || text(source.gmail_body);
  var waText = text(item.wa_text) || text(source.wa_text);
  var waTemplate = text(item.wa_template_name) || text(source.wa_template_name);
  var channel = text(item.channel || source.channel).toLowerCase();
  var messageComplete = channel === 'gmail'
    ? Boolean(subject && body)
    : Boolean(waText || waTemplate);

  if (reason.indexOf('message incomplete') !== -1 && position && newMissing.length === 0 && messageComplete) {
    var fixed = Object.assign({}, item, source, {
      position: position,
      gmail_subject: subject,
      gmail_body: body,
      wa_text: waText,
      wa_template_name: waTemplate,
      missing_fields: [],
      status: 'ready',
      reason: '',
      restored_after_approval: true,
      position_rehydrated: true
    });
    output.push({ json: fixed });
  } else {
    diagnostics.push({
      row_number: item.row_number,
      name: item.name,
      status: item.status,
      reason: item.reason,
      position_found: position,
      missing_fields: missing,
      message_complete: messageComplete,
      hint: position
        ? 'Position found, but message fields are still incomplete. Run workflow from the beginning.'
        : 'Position was not found in upstream nodes. Check the Contacts header/value and rerun from the start.'
    });
  }
}

if (output.length) return output;

return [{
  json: {
    _empty: true,
    target_found: false,
    restore_error: 'No complete ready message could be restored.',
    diagnostics: diagnostics,
    hint: 'After editing the Contacts sheet, execute the workflow from Admin Start. Do not execute only this node.'
  }
}];

// Read the Admin run-control sheet (RUN / PAUSE / STOP) and attach the state to the current message
const rows = $input.all().map(i => i.json);
const st = String(rows[0]?.Status ?? rows[0]?.status ?? 'RUN').trim().toUpperCase();
const loopItem = $('Loop Over Messages').first().json;
return [{ json: { ...loopItem, run_state: ['PAUSE', 'STOP'].includes(st) ? st : 'RUN' } }];

// ---------- shared helpers ----------
const normKey = s => String(s ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
const lev = (a, b) => {
  if (a === b) return 0;
  const m = a.length, n = b.length;
  if (!m) return n;
  if (!n) return m;
  let prev = Array.from({ length: n + 1 }, (_, j) => j);
  for (let i = 1; i <= m; i++) {
    const cur = [i];
    for (let j = 1; j <= n; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = cur;
  }
  return prev[n];
};
const sim = (a, b) => {
  const na = normKey(a), nb = normKey(b);
  if (!na || !nb) return 0;
  if (na === nb) return 1;
  if (Math.min(na.length, nb.length) >= 3 && (na.includes(nb) || nb.includes(na))) return 0.9;
  return 1 - lev(na, nb) / Math.max(na.length, nb.length);
};
const toList = v => Array.isArray(v)
  ? v.map(x => String(x).trim()).filter(Boolean)
  : String(v ?? '').split(/[,;\n]+/).map(s => s.trim()).filter(Boolean);
const digitsOf = v => String(v ?? '').replace(/\D/g, '');
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const getter = row => {
  const map = {};
  for (const k of Object.keys(row || {})) map[normKey(k)] = row[k];
  return (...names) => {
    for (const n of names) {
      const v = map[normKey(n)];
      if (v !== undefined && v !== null && String(v).trim() !== '') return v;
    }
    return '';
  };
};
const safeAll = name => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };

// ==========================================
// FINALIZE: combine send results + skipped/blocked, build status rows, log rows and report
// ==========================================
const cfg = $('Validate Configuration').first().json;
const results = $input.all().map(i => i.json).filter(r => r && r.channel);
const validated = safeAll('Validate & Duplicate Check').filter(v => v.channel);
const nonReady = validated.filter(v => v.status !== 'ready');
const nowIso = new Date().toISOString();
const today = nowIso.slice(0, 10);

const label = (r) => {
  if (r.send_status === 'Sent') return 'Sent';
  if (r.send_status === 'Failed') return r.reason ? `Failed: ${r.reason}` : 'Failed';
  return r.reason ? `Skipped: ${r.reason}` : 'Skipped';
};
const persons = new Map();
const seedPerson = v => {
  if (!persons.has(v.row_number)) persons.set(v.row_number, {
    row_number: v.row_number,
    'Gmail Status': v.existing_gmail_status || '',
    'WhatsApp Status': v.existing_wa_status || '',
    'Last Contacted': v.existing_last_contacted || ''
  });
  return persons.get(v.row_number);
};
validated.forEach(seedPerson);
const setStatus = (rn, ch, text, sent) => {
  const p = persons.get(rn);
  if (!p) return;
  p[ch === 'gmail' ? 'Gmail Status' : 'WhatsApp Status'] = text;
  if (sent) p['Last Contacted'] = today;
};
for (const r of results) setStatus(r.row_number, r.channel, label(r), r.send_status === 'Sent');
for (const v of nonReady) setStatus(v.row_number, v.channel, `${v.status === 'skipped' ? 'Skipped' : 'Blocked'}: ${v.reason}`, false);

const touched = new Set([...results.map(r => r.row_number), ...nonReady.map(v => v.row_number)]);
const out = [];
for (const rn of touched) out.push({ json: { _kind: 'status', ...persons.get(rn) } });

const logRow = (o) => ({ _kind: 'log', Timestamp: nowIso, 'Run ID': cfg.run_id, Event: '', Channel: '', Name: '', Email: '', Mobile: '', Package: cfg.package, Status: '', Reason: '', 'Message ID': '', ...o });
for (const v of nonReady) {
  out.push({ json: logRow({ Event: v.status === 'skipped' ? 'skip' : 'blocked', Channel: v.channel, Name: v.name, Email: v.email, Mobile: v.mobile_clean, Status: v.status === 'skipped' ? 'Skipped' : 'Blocked', Reason: v.reason }) });
}
if (cfg.target_type === 'search') {
  const matches = safeAll('Smart Search').filter(r => !r._empty);
  out.push({ json: logRow({ Event: 'search', Status: `${matches.length} match(es)`, Reason: String(cfg.search_query || '').slice(0, 200) }) });
}
if (cfg.require_admin_approval) out.push({ json: logRow({ Event: 'approval', Status: 'Approved' }) });

const count = (s) => results.filter(r => r.send_status === s).length;
const sent = count('Sent'), failed = count('Failed');
const stopped = results.filter(r => r.send_status === 'Skipped').length;
const by = ch => results.filter(r => r.channel === ch && r.send_status === 'Sent').length;
const failList = results.filter(r => r.send_status === 'Failed').map(r => `<li>${esc(r.name)} (${r.channel}): ${esc(r.reason)}</li>`).join('');
const blockList = nonReady.slice(0, 25).map(v => `<li>${esc(v.name)} (${v.channel}): ${esc(v.status)}, ${esc(v.reason)}</li>`).join('');
const html = `<h3>Run ${esc(cfg.run_id)} finished</h3>
<p><b>Sent:</b> ${sent} (Gmail ${by('gmail')}, WhatsApp ${by('whatsapp')})<br><b>Failed:</b> ${failed}<br>
<b>Stopped by Admin:</b> ${stopped}<br><b>Skipped (already sent):</b> ${nonReady.filter(v => v.status === 'skipped').length}<br>
<b>Blocked:</b> ${nonReady.filter(v => v.status === 'blocked').length}</p>
${failed ? `<h4>Failures</h4><ul>${failList}</ul>` : ''}
${nonReady.length ? `<h4>Skipped / blocked</h4><ul>${blockList}</ul>${nonReady.length > 25 ? '<p>… see the Send Log sheet for the rest.</p>' : ''}` : ''}
<p>WhatsApp delivery updates (delivered / read) arrive later and are written to the sheet automatically.</p>`;
out.push({ json: logRow({ Event: 'run', Status: `${sent} sent, ${failed} failed`, Reason: `skipped/blocked: ${nonReady.length}` }) });
out.push({ json: { _kind: 'report', subject: `Run ${cfg.run_id} finished: ${sent} sent, ${failed} failed`, html } });
return out;
